def pad_text_to_characters_length(text, characters):
    lines = text.split(os.linesep)
    if len(lines) == 1:
        return text

    result = []
    result.append(lines[0])

    for line in lines[1:]:
        if not line:
            continue

        pad = len(line) + len(characters)
        result.append(line.rjust(pad))

    return os.linesep.join(result)

