def bfs(G, source, sink, parent):
    visited = [False] * len(G)

    queue = deque()
    queue.append(source)

    visited[source] = True

    while queue:
        node = queue.popleft()

        for i in range(len(G[node])):
            if visited[i] is False and G[node][i] > 0:
                queue.append(i)
                visited[i] = True
                parent[i] = node

    return True if visited[sink] else False

code.after:
def bfs(G, source, sink, parent):
    visited = set()

    queue = deque()
    queue.append(source)

    visited.add(source)

    while queue:
        node = queue.popleft()

        for i in range(len(G[node])):
            if i not in visited and G[node][i] > 0:
                queue.append(i)
                visited.add(i)
                parent[i] = node

    return sink in visited

